mapper.select:
SELECT ft.id AS task_id, ft.instance_id, fi.definition_id, fi.business_id, fd.name AS process_name, fd.code AS process_code, fi.category, ft.node_key, ft.node_name, fi.user_id AS start_user_id, fi.start_time AS instance_start_time, ft.start_time AS task_start_time, ft.end_time AS task_end_time, ft.status, ft.comment, ft.require_comment FROM flow_task ft INNER JOIN flow_instance fi ON fi.id = ft.instance_id AND fi.org_id = ft.org_id INNER JOIN flow_definition fd ON fd.id = fi.definition_id AND fd.org_id = ft.org_id
ft.org_id = #{query.orgId} AND ft.assignee = #{query.assignee} AND ft.is_delete = 0
AND ft.node_type = 1 AND ft.status IN
#{status}
AND (fd.name LIKE CONCAT('%', #{query.keyword}, '%') OR fd.code LIKE CONCAT('%', #{query.keyword}, '%'))
AND fi.category = #{query.category}
AND ft.start_time >= #{query.taskStartTimeBegin}
AND ft.start_time <= #{query.taskStartTimeEnd}
AND ft.end_time >= #{query.taskEndTimeBegin}
AND ft.end_time <= #{query.taskEndTimeEnd}
ORDER BY COALESCE(ft.end_time, ft.start_time) DESC, ft.id DESC
